  function callGasApi(action, payload) {
    if (!GAS_API_URL || GAS_API_URL.indexOf('PASTE_YOUR_DEPLOYED') === 0) {
      return Promise.reject(new Error('GAS_API_URL is not configured yet in app.js'));
    }
    return fetch(GAS_API_URL, {
      method: 'POST',
      // text/plain avoids CORS preflight issues with Google Apps Script doPost(e)
      headers: { 'Content-Type': 'text/plain;charset=utf-8' },
      body: JSON.stringify({ action: action, payload: payload || {} })
    }).then(function(resp) {
      return resp.json();
    });
  }

