  function runBackend(fnName, payload, onSuccess, onFailure) {
    if (typeof google !== 'undefined' && google.script && google.script.run) {
      var runner = google.script.run
        .withSuccessHandler(function(res) { if (onSuccess) onSuccess(res); })
        .withFailureHandler(function(err) { if (onFailure) onFailure(err); });
      if (payload !== undefined) {
        runner[fnName](payload);
      } else {
        runner[fnName]();
      }
      return;
    }
    if (GAS_API_URL && GAS_API_URL.indexOf('https://script.google.com/') === 0) {
      callGasApi(fnName, payload)
        .then(function(res) { if (onSuccess) onSuccess(res); })
        .catch(function(err) { if (onFailure) onFailure(err); });
      return;
    }
    if (onFailure) onFailure(new Error('No backend configured'));
  }

  function roundMoney(n) {
    var val = Number(n || 0);
    if (isNaN(val)) return 0;
    return Math.round((val + Number.EPSILON) * 100) / 100;
  }

  function formatDateDisplay(isoDate) {
    if (!isoDate) return '';
    var parts = String(isoDate).split('-');
    if (parts.length !== 3) return isoDate;
    var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    var m = parseInt(parts[1], 10) - 1;
    var d = parseInt(parts[2], 10);
    return (d < 10 ? '0' + d : d) + ' ' + (months[m] || parts[1]) + ' ' + parts[0];
  }

  function formatSeqInvoiceNumber(prefix, seq, pad) {
    var s = String(Math.max(1, Number(seq || 1)));
    var p = Number(pad || 4);
    while (s.length < p) s = '0' + s;
    return String(prefix || 'LL-2026-') + s;
  }

  function showToast(msg) {
    var el = document.getElementById('appToast');
    if (!el) return;
    el.textContent = msg;
    el.classList.remove('hidden');
    clearTimeout(window.__toastTimer);
    window.__toastTimer = setTimeout(function() {
      el.classList.add('hidden');
    }, 3400);
  }

