  function switchTab(tabName) {
    ['create', 'history', 'products', 'customers', 'settings'].forEach(function(t) {
      var sec = document.getElementById('tab-' + t);
      if (sec) sec.classList.toggle('hidden', t !== tabName);
      var dBtn = document.getElementById('nav-desk-' + t);
      if (dBtn) {
        dBtn.className = (t === tabName)
          ? 'px-3 py-1.5 rounded text-xs font-semibold bg-[#B08D4A] text-black transition'
          : 'px-3 py-1.5 rounded text-xs font-semibold text-neutral-300 hover:text-white hover:bg-neutral-800 transition';
      }
      var mBtn = document.getElementById('nav-mob-' + t);
      if (mBtn) {
        mBtn.className = (t === tabName)
          ? 'flex flex-col items-center justify-center gap-1 text-black font-bold border-t-2 border-[#B08D4A]'
          : 'flex flex-col items-center justify-center gap-1 text-neutral-500';
      }
    });
    if (tabName === 'create') {
      setTimeout(scaleInvoicePaperForMobile, 60);
    }
  }

  function toggleMobileInvoicePane(mode) {
    var formPane = document.getElementById('mobileFormPane');
    var prevPane = document.getElementById('mobilePreviewPane');
    var btnForm = document.getElementById('mob-view-form-btn');
    var btnPrev = document.getElementById('mob-view-preview-btn');
    if (mode === 'preview') {
      formPane.classList.add('hidden', 'lg:block');
      prevPane.classList.remove('hidden');
      btnPrev.className = 'flex-1 py-2 rounded-lg text-xs font-bold bg-black text-white transition';
      btnForm.className = 'flex-1 py-2 rounded-lg text-xs font-bold text-neutral-600 transition';
      setTimeout(scaleInvoicePaperForMobile, 50);
    } else {
      prevPane.classList.add('hidden');
      formPane.classList.remove('hidden');
      btnForm.className = 'flex-1 py-2 rounded-lg text-xs font-bold bg-black text-white transition';
      btnPrev.className = 'flex-1 py-2 rounded-lg text-xs font-bold text-neutral-600 transition';
    }
  }

  function scaleInvoicePaperForMobile() {
    var wrapper = document.getElementById('invoicePreviewWrapper');
    var container = document.getElementById('invoiceScaleContainer');
    var sheet = document.getElementById('excelInvoiceSheet');
    if (!wrapper || !container || !sheet) return;
    var availWidth = wrapper.clientWidth - 16;
    if (availWidth > 0 && availWidth < 794) {
      var scale = availWidth / 794;
      container.style.transform = 'scale(' + scale + ')';
      container.style.width = '794px';
      container.style.height = Math.ceil(sheet.offsetHeight * scale) + 'px';
    } else {
      container.style.transform = 'none';
      container.style.width = 'auto';
      container.style.height = 'auto';
    }
  }

